    expect(err.status).toBe(401);
  });

  it('usuario inexistente -> HttpError 401', async () => {
    const { next } = await run({ 'x-user-id': 'fantasma' });
    expect(next.mock.calls[0][0]).toMatchObject({ status: 401 });
  });
});
